import sys
from collections import deque

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        N, M, K = map(int, sys.stdin.readline().split())
        if N == 1 or M == 1:
            print(K)
            continue
        total_cells = (N-2)*(M-2)
        if K <= total_cells:
            print(1)
        else:
            print((K + total_cells - 1) // total_cells)

solve()
